<script setup lang="ts">
import { computed, toRaw, onMounted, onUnmounted, reactive, ref } from 'vue';
import { Plus, RefreshCw, Server, Settings2, Download, Trash2, X } from 'lucide-vue-next';
import { useApi, isCancelled } from '../lib/api';
import { download } from '../lib/download';
import { usePanelContext } from '../composables/panelContext';
import TablePageLayout from '../components/TablePageLayout.vue';
import QualityTags from '../QualityTags.vue';
import type { Node } from '../types';
import { t } from '../i18n';
type Grant={user_id:number;quota:number};
type Template={id:string;name:string;exit_id:string;protocol:string;enabled:boolean;reality_sni?:string;dns?:{mode:string;doh?:string;ipv6?:string}};
type Site={id:string;name:string;group:string;enabled:boolean;exclusive:boolean;revision:string;last_seen:number;applied:string;desired:string;lease_until:number;error:string;info?:{version:string;vless_host:string;hy2_host:string};nodes:Template[];grants:Grant[];reports?:Node[];commands?:{node_id:string;kind:string;state:string}[];usage?:Record<string,{upload:number;download:number}>};
const api=useApi('/business-sites');const {state,refresh,bytes}=usePanelContext();
const sites=ref<Site[]>([]),error=ref(''),busy=ref(false),loaded=ref(false),editing=ref<Site|null>(null),creating=ref(false),removing=ref<Site|null>(null),enrollment=ref<Record<string,string>|null>(null);
const createForm=reactive({id:'',name:'',group:''});const members=ref<Record<number,{selected:boolean;gib:number}>>({});
const allUsers=computed(()=>state.value?.users||[]);const pools=computed(()=>(state.value?.ip_pool||[]).filter(p=>p.enabled));
const online=computed(()=>sites.value.filter(s=>s.last_seen>Date.now()/1000-90).length);
const siteStatus=(s:Site)=>!s.info?'等待注册':s.error?'配置异常':!s.enabled?'已停用':s.lease_until<=Date.now()/1000?'授权已过期':s.last_seen<Date.now()/1000-90?'连接中断':s.applied!==s.desired?'等待同步':'已同步';
async function load(){try{const out=await api<{sites:Site[]}>();sites.value=out.sites.map(s=>({...s,nodes:s.nodes||[],grants:s.grants||[]}));loaded.value=true;error.value='';}catch(e){if(!isCancelled(e))error.value=(e as Error).message;}}
function edit(site:Site){editing.value=structuredClone(toRaw(site));members.value={};for(const user of allUsers.value){const g=site.grants.find(g=>g.user_id===user.id);members.value[user.id]={selected:!!g,gib:g?g.quota/1073741824:0};}error.value='';}
function close(){if(busy.value)return;editing.value=null;creating.value=false;removing.value=null;enrollment.value=null;error.value='';}
async function create(){busy.value=true;try{const out=await api<{enrollment:Record<string,string>}>('','POST',createForm);enrollment.value=out.enrollment;await load();}catch(e){if(!isCancelled(e))error.value=(e as Error).message;}finally{busy.value=false;}}
function registrationFile(){if(enrollment.value)download(new Blob([JSON.stringify(enrollment.value,null,2)+'\n'],{type:'application/json'}),'guangyue-'+enrollment.value.site_id+'-enrollment.json');}
function addNode(){if(!editing.value||!pools.value.length)return;editing.value.nodes.push({id:'node_'+crypto.randomUUID().slice(0,8),name:'',protocol:'vless',exit_id:pools.value[0].id,enabled:true,dns:{mode:'secure',doh:'https://1.1.1.1/dns-query',ipv6:'block'}});}
async function save(){const s=editing.value;if(!s)return;busy.value=true;error.value='';try{const grants=Object.entries(members.value).filter(([,v])=>v.selected).map(([id,v])=>({user_id:Number(id),quota:Math.round(v.gib*1073741824)}));await api('/'+s.id,'PUT',{name:s.name,group:s.group,enabled:s.enabled,exclusive:s.exclusive,revision:s.revision,nodes:s.nodes,grants});editing.value=null;await load();await refresh();}catch(e){if(!isCancelled(e))error.value=(e as Error).message;}finally{busy.value=false;}}
async function remove(){if(!removing.value)return;busy.value=true;try{await api('/'+removing.value.id,'DELETE',{});removing.value=null;await load();}catch(e){if(!isCancelled(e))error.value=(e as Error).message;}finally{busy.value=false;}}
async function detect(n:Node,kind:string){if(!editing.value)return;busy.value=true;error.value='';try{await api('/'+editing.value.id+'/tasks','POST',{kind,node_id:n.id});await load();editing.value.commands=sites.value.find(s=>s.id===editing.value?.id)?.commands;}catch(e){if(!isCancelled(e))error.value=(e as Error).message;}finally{busy.value=false;}}
let timer:ReturnType<typeof setInterval>;onMounted(()=>{load();timer=setInterval(()=>{if(!busy.value&&!editing.value&&!creating.value&&!removing.value)load();},15000);});onUnmounted(()=>{clearInterval(timer);enrollment.value=null;});
</script>
<template>
<div class="business-page">
 <div class="business-tabs"><RouterLink to="/fleet" class="active">{{t('业务站')}}</RouterLink><RouterLink to="/fleet/independent">{{t('独立面板接入')}}</RouterLink></div>
 <div class="business-summary"><div><Server :size="20"/><span>{{t('主控站')}}</span><strong>{{state?.system.site_id}}</strong></div><div><span>{{t('业务站')}}</span><strong>{{sites.length}} <small>/ 64</small></strong></div><div><span>{{t('在线站点')}}</span><strong>{{online}}</strong></div><div><span>{{t('授权有效期')}}</span><strong>15 <small>{{t('分钟')}}</small></strong></div></div>
 <TablePageLayout :title="t('主控站与业务站')" :description="t('统一管理成员、出口分配和订阅；每台业务站独立运行代理核心')">
  <template #actions><button @click="load" :disabled="busy"><RefreshCw :size="15"/>{{t('刷新')}}</button><button class="primary" @click="creating=true;enrollment=null;error='' "><Plus :size="16"/>{{t('添加业务站')}}</button></template>
  <template #notice><p class="pool-intro">{{t('业务站主动连接主控，保留默认 VLESS / HY2 直连。分配的出口会创建附加节点，统一订阅只展示已授权且已同步的站点。')}}</p><p v-if="error&&!editing&&!creating&&!removing" class="error" role="alert">{{t(error)}}</p></template>
  <table><thead><tr><th>{{t('站点名称')}}</th><th>{{t('连接状态')}}</th><th>{{t('节点与成员')}}</th><th>{{t('最近同步')}}</th><th>{{t('操作')}}</th></tr></thead><tbody>
   <tr v-for="s in sites" :key="s.id"><td><strong>{{s.name}}</strong><small>{{s.group||'—'}} · {{s.id}}</small></td><td><span :class="['badge',siteStatus(s)==='已同步'?'success':'neutral']">{{t(siteStatus(s))}}</span><small v-if="s.info">v{{s.info.version}}</small></td><td>{{s.nodes.length+2}} {{t('节点')}} · {{s.grants.length}} {{t('成员')}}<small>{{t(s.exclusive?'独占出口':'共享出口')}}</small></td><td>{{s.last_seen?new Date(s.last_seen*1000).toLocaleString():'—'}}</td><td><div class="row-actions"><button @click="edit(s)"><Settings2 :size="14"/>{{t('配置')}}</button><button class="icon" :aria-label="t('删除业务站')+' '+s.name" @click="removing=s;error='' "><Trash2 :size="15"/></button></div></td></tr>
   <tr v-if="!sites.length"><td colspan="5" class="empty">{{t(loaded?'尚未添加业务站':'加载中…')}}</td></tr>
  </tbody></table>
 </TablePageLayout>
 <Teleport to="body"><div v-if="creating||editing||removing" class="message-overlay" @click.self="close">
  <form v-if="creating" class="compose-card" role="dialog" aria-modal="true" :aria-label="t('添加业务站')" @submit.prevent="create"><header><h2>{{t('添加业务站')}}</h2><button type="button" class="icon" :disabled="busy" @click="close" :aria-label="t('关闭')"><X/></button></header><p v-if="error" class="error" role="alert">{{t(error)}}</p>
   <template v-if="!enrollment"><label>{{t('站点名称')}}<input v-model="createForm.name" maxlength="64" required/></label><label>{{t('站点标识')}}<input v-model="createForm.id" pattern="[a-z][a-z0-9_]{0,39}" placeholder="site_tokyo" required/></label><label>{{t('分组')}}<input v-model="createForm.group" maxlength="40"/></label><p class="field-help">{{t('站点标识创建后不可修改。注册文件有效期为 24 小时，首次同步后自动失效。')}}</p><footer><button type="button" :disabled="busy" @click="close">{{t('取消')}}</button><button class="primary" :disabled="busy">{{t('创建注册文件')}}</button></footer></template>
   <template v-else><p>{{t('请下载注册文件，在新 VPS 上安装 Pro 并选择 business 角色。注册文件仅在此处提供，请妥善保管。')}}</p><button type="button" class="primary" @click="registrationFile"><Download :size="16"/>{{t('下载注册文件')}}</button><p class="field-help">{{t('安装参数：--role business --enrollment-file /root/enrollment.json。完整步骤见安装包 docs/BUSINESS-SITES.md。')}}</p><footer><button type="button" :disabled="busy" @click="close">{{t('完成')}}</button></footer></template>
  </form>
  <form v-else-if="editing" class="compose-card business-editor" role="dialog" aria-modal="true" :aria-label="t('业务站配置')" @submit.prevent="save"><header><h2>{{t('业务站配置')}} · {{editing.id}}</h2><button type="button" class="icon" :disabled="busy" @click="close" :aria-label="t('关闭')"><X/></button></header><p v-if="error" class="error" role="alert">{{t(error)}}</p>
   <div class="field-pair"><label>{{t('站点名称')}}<input v-model="editing.name" maxlength="64" required/></label><label>{{t('分组')}}<input v-model="editing.group" maxlength="40"/></label></div>
   <div class="row-actions"><label class="check-label"><input v-model="editing.enabled" type="checkbox"/>{{t('启用站点')}}</label><label class="check-label"><input v-model="editing.exclusive" type="checkbox"/>{{t('独占出口')}}</label></div>
   <section><h3>{{t('成员与额度')}}</h3><p class="field-help">{{t('额度为本站累计流量上限，单位 GiB；0 仅适用于总配额无限的成员。未消费的额度会从主控可用额度中预留。')}}</p><div class="business-members"><div v-for="u in allUsers.filter(user=>members[user.id])" :key="u.id"><label class="check-label"><input v-model="members[u.id].selected" type="checkbox"/>{{u.username}}</label><input v-model.number="members[u.id].gib" :disabled="!members[u.id].selected" type="number" min="0" step="any" :aria-label="u.username+' GiB'"/><small>{{t('已使用')}} {{bytes((editing.usage?.[u.id]?.upload||0)+(editing.usage?.[u.id]?.download||0))}}</small></div></div></section>
   <section><div class="section-heading"><h3>{{t('附加节点与出口')}}</h3><button type="button" @click="addNode" :disabled="!pools.length||editing.nodes.length>=14"><Plus :size="14"/>{{t('新增节点')}}</button></div><p class="field-help">{{t('默认 VLESS / HY2 直连始终保留，不占用 IP 池。公共出口产生的节点仅出现在公共订阅。')}}</p>
   <div v-for="(n,i) in editing.nodes" :key="n.id" class="business-node"><div class="node-fields"><label>{{t('协议')}}<select v-model="n.protocol"><option value="vless">VLESS</option><option value="hy2">HY2</option></select></label><label>{{t('出口')}}<select v-model="n.exit_id" required><option v-if="!pools.some(p=>p.id===n.exit_id)" :value="n.exit_id">{{t('出口已删除')}}</option><option v-for="p in pools" :key="p.id" :value="p.id">{{p.pool_group==='public'?t('公共'):t('私有')}} · {{p.label||p.name}} · {{p.probe_ip||p.host}}</option></select></label><button class="icon" type="button" :aria-label="t('移除节点')" @click="editing.nodes.splice(i,1)"><Trash2 :size="15"/></button></div><div class="field-pair"><label v-if="n.protocol==='vless'">SNI<input v-model="n.reality_sni" :placeholder="t('使用业务站默认 SNI')"/></label><label>{{t('出口 DNS 防护')}}<select :value="n.dns?.mode||'system'" @change="n.dns=($event.target as HTMLSelectElement).value==='secure'?{mode:'secure',doh:'https://1.1.1.1/dns-query',ipv6:'block'}:{mode:'system'}"><option value="secure">{{t('开启 IPv4 防护并阻止 IPv6')}}</option><option value="system">{{t('常规模式')}}</option></select></label></div><label class="check-label"><input type="checkbox" v-model="n.enabled"/>{{t('启用节点')}}</label></div></section>
   <section v-if="editing.reports?.length"><h3>{{t('节点质量报告')}}</h3><div v-for="n in editing.reports" :key="n.id" class="business-report"><span>{{n.name}} · {{n.protocol.toUpperCase()}}</span><QualityTags :value="n.quality" :name="n.name" read-only/><div class="row-actions"><button type="button" :disabled="busy" @click="detect(n,'quality')">{{t('检测质量')}}</button><button type="button" :disabled="busy" @click="detect(n,'speed')">{{t('测速')}}</button><small v-for="cmd in editing.commands?.filter(c=>c.node_id===n.id)" :key="cmd.kind">{{cmd.kind}} · {{cmd.state}}</small></div></div></section>
   <p class="field-help">{{t('变更在业务站下一次同步后生效；断连最多保留 15 分钟授权。删除站点前请停用并取消全部成员，等待确认撤销。')}}</p><footer><button type="button" :disabled="busy" @click="close">{{t('取消')}}</button><button class="primary" :disabled="busy">{{t('保存配置')}}</button></footer>
  </form>
  <section v-else-if="removing" class="compose-card" role="alertdialog" aria-modal="true"><h2>{{t('删除业务站')}} · {{removing.name}}</h2><p>{{t('站点必须已停用、清空成员并确认撤销后才能删除。业务服务器上的软件和证书保留。')}}</p><p v-if="error" class="error" role="alert">{{t(error)}}</p><footer><button @click="close" :disabled="busy">{{t('取消')}}</button><button class="danger-button" @click="remove" :disabled="busy">{{t('确认删除')}}</button></footer></section>
 </div></Teleport>
</div>
</template>
<style scoped>
.business-page{display:flex;flex-direction:column;gap:24px}.business-tabs{display:flex;gap:24px;border-bottom:1px solid var(--border);padding-bottom:14px}.business-tabs a{font-size:13px;color:var(--muted)}.business-tabs .active{color:var(--accent-text);font-weight:600}.business-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.business-summary>div{display:flex;flex-direction:column;gap:10px;border:1px solid var(--border);border-radius:12px;padding:20px;background:var(--surface)}.business-summary span,small{font-size:11px;color:var(--muted)}.business-summary strong{font-size:23px;font-weight:600}.business-page td small{display:block;margin-top:7px}.row-actions,.section-heading{display:flex;align-items:center;gap:12px}.section-heading{justify-content:space-between}.business-editor{width:min(820px,calc(100vw - 32px));max-height:90dvh;overflow:auto}.field-pair,.node-fields{display:grid;grid-template-columns:1fr 1fr;gap:14px}.node-fields{grid-template-columns:110px minmax(0,1fr) 30px;align-items:end}.business-editor section{border-top:1px solid var(--border);padding-top:16px}.business-editor h3{font-size:14px;margin:0 0 14px}.business-members{display:flex;flex-direction:column;gap:10px;max-height:250px;overflow:auto}.business-members>div{display:grid;grid-template-columns:1fr 110px 130px;align-items:center;gap:12px}.business-editor .check-label{display:flex;flex-direction:row;align-items:center;gap:8px;margin:0}.check-label input{width:16px;height:16px}.business-node{border:1px solid var(--border);border-radius:9px;padding:14px;display:flex;flex-direction:column;gap:12px;margin-top:12px}.business-report{font-size:12px;padding:12px 0;display:flex;flex-direction:column;gap:8px}@media(max-width:700px){.business-summary{grid-template-columns:1fr 1fr}.business-members>div{grid-template-columns:1fr 90px}.business-members small{grid-column:1/-1}.field-pair{grid-template-columns:1fr}}
</style>
